typedef struct ExprNode {
    char symbol; // operator, or digit character if leaf
    int isOperator;
    struct ExprNode* left;
    struct ExprNode* right;
} ExprNode;

int evaluate(ExprNode* node) {
    if (!node->isOperator) return node->symbol - '0';
    int l = evaluate(node->left);
    int r = evaluate(node->right);
    switch (node->symbol) {
        case '+': return l + r;
        case '*': return l * r;
    }
    return 0;
}

